using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

tests.code:
var t = new Solution.Temperature(25.0);
Cj.Near(t.Celsius, 25.0, 1e-9, "celsius kept");
var boil = Solution.Temperature.FromFahrenheit(212.0);
Cj.Near(boil.Celsius, 100.0, 1e-9, "water boils at 100C");
var freeze = Solution.Temperature.FromFahrenheit(32.0);
Cj.Near(freeze.Celsius, 0.0, 1e-9, "water freezes at 0C");

bool t1 = false;
try { new Solution.Temperature(-273.16); } catch (ArgumentException) { t1 = true; }
var edge = new Solution.Temperature(-273.15);
Cj.Near(edge.Celsius, -273.15, 1e-9, "exact absolute zero is legal");
bool t2 = false;
try { Solution.Temperature.FromFahrenheit(-500.0); } catch (ArgumentException) { t2 = true; }
Cj.True(t1 && t2, "below absolute zero rejected on both paths");
